std::unique_ptr<Payoff> make_payoff(const std::string& kind, double strike) {
    if (kind == "call") return std::make_unique<CallPayoff>(strike);
    if (kind == "put")  return std::make_unique<PutPayoff>(strike);
    return nullptr;                       // 不认识的类型
}

